/**
 * Prove the live YouCam Skin Analysis connection with an actual face.
 *
 * Every earlier probe used a synthetic JPEG, which the analyser correctly refused
 * for having no face in it. That proved the transport, the storage, the consent gate
 * and the error path - but it could never prove the part that matters: that a real
 * analysis comes back, parses, stores, and can be read out again with its regions
 * intact.
 *
 * There is no face photograph in this repository to test with, so the face is
 * generated by YouCam's own text-to-image endpoint. That keeps the test free of any
 * real person's biometrics while still exercising the identical code path.
 *
 * Pass the generated image URL as the first argument.
 */

import { readFileSync, writeFileSync } from 'node:fs';

const BASE = readFileSync('deployed-url.txt', 'utf8').trim().replace(/\/+$/, '');
const CODE = readFileSync('access-code.txt', 'utf8').trim();
const IMAGE_URL = process.argv[2];

if (!IMAGE_URL) {
  console.error('usage: node scripts/probe-live-face.mjs <image-url>');
  process.exit(1);
}

const out = [];
const log = (l) => {
  out.push(l);
  console.log(l);
};

// ------------------------------------------------------------------- fetch

const imageRes = await fetch(IMAGE_URL);
const image = Buffer.from(await imageRes.arrayBuffer());
log(`image: ${imageRes.status}, ${(image.length / 1024).toFixed(0)} KB`);

if (!imageRes.ok) {
  writeFileSync('probe-live-face.txt', out.join('\n'));
  process.exit(1);
}

// ----------------------------------------------------------------- session

const token = (
  await (
    await fetch(`${BASE}/session`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: `face+${Date.now()}@example.com`, code: CODE }),
    })
  ).json()
).token;
const auth = { Authorization: `Bearer ${token}` };
log('signed in');

// ------------------------------------------------------------------ create

const form = new FormData();
form.set('image', new Blob([image], { type: 'image/jpeg' }), 'check-in.jpg');
form.set(
  'meta',
  JSON.stringify({
    source: 'declared',
    preset: 'MODERATE',
    lightingLevel: 0.64,
    lightingUneven: 0.06,
    faceRatio: 0,
    yaw: 0,
    pitch: 0,
    roll: 0,
    measured: ['lighting'],
  }),
);

const createRes = await fetch(`${BASE}/v1/scans`, { method: 'POST', headers: auth, body: form });
const created = await createRes.json();
log(`POST /v1/scans -> ${createRes.status}  tier=${created?.scan?.tier} id=${created?.scan?.id}`);

const id = created?.scan?.id;
if (!id) {
  log('FAIL: no scan created');
  writeFileSync('probe-live-face.txt', out.join('\n'));
  process.exit(1);
}

// -------------------------------------------------------- consent, analyse

await fetch(`${BASE}/v1/scans/${id}/consent`, {
  method: 'POST',
  headers: { ...auth, 'Content-Type': 'application/json' },
  body: JSON.stringify({ agree: true }),
});
const startRes = await fetch(`${BASE}/v1/scans/${id}/analyse`, { method: 'POST', headers: auth });
log(`POST /analyse -> ${startRes.status}`);

// -------------------------------------------------------------------- poll

let detail = null;
const started = Date.now();
for (let i = 0; i < 40; i += 1) {
  // eslint-disable-next-line no-await-in-loop
  detail = await (await fetch(`${BASE}/v1/scans/${id}`, { headers: auth })).json();
  const status = detail.scan?.status;
  log(
    `poll ${i} (${Math.round((Date.now() - started) / 1000)}s): ${status}  readings=${detail.readings?.length ?? 0} masks=${detail.masks?.length ?? 0}`,
  );
  if (status === 'succeeded' || status === 'failed') break;
  // eslint-disable-next-line no-await-in-loop
  await new Promise((r) => setTimeout(r, 3000));
}

// ----------------------------------------------------------------- verdict

if (detail?.scan?.status !== 'succeeded') {
  log(`RESULT: not succeeded. error=${JSON.stringify(detail?.error)}`);
  writeFileSync('probe-live-face.txt', out.join('\n'));
  process.exit(1);
}

log('');
log('=== WHAT CAME BACK ===');
log(`overall score: ${detail.scan.overallScore}`);
log(`skin age:      ${detail.scan.skinAge}`);
log(`readings:      ${detail.readings.length}`);
log(`masks:         ${detail.masks.length}`);
log(`photo url:     ${detail.photoUrl ? 'presigned, present' : 'MISSING'}`);

// Grouped, so the multi-region metrics are visible rather than buried. These are
// the ones a single-number-per-metric UI would have thrown away.
const byMetric = new Map();
for (const r of detail.readings) {
  const list = byMetric.get(r.metric) ?? [];
  list.push(r);
  byMetric.set(r.metric, list);
}
log('');
for (const [metric, readings] of [...byMetric.entries()].sort()) {
  const parts = readings
    .map((r) => `${r.region}=${r.rawScore ?? r.categoryValue ?? '—'}`)
    .join(' ');
  log(`  ${metric.padEnd(20)} ${readings.length} region(s)  ${parts}`);
}

log('');
log(`multi-region metrics: ${[...byMetric.entries()].filter(([, v]) => v.length > 1).map(([k, v]) => `${k}(${v.length})`).join(', ') || 'none'}`);

// A presigned mask URL that does not actually resolve would look fine in the API
// response and render as a broken image in the app.
if (detail.masks[0]) {
  const maskRes = await fetch(detail.masks[0].url);
  log(`first mask fetch: ${maskRes.status} ${maskRes.headers.get('content-type')}`);
}
const photoRes = await fetch(detail.photoUrl);
log(`photo fetch:      ${photoRes.status} ${photoRes.headers.get('content-type')}`);

writeFileSync('probe-live-face.txt', out.join('\n'));
